import testNapi, { nativeAddExternalNode } from 'libentry.so';
import { CanvasPage } from './CanvasPage';
import { XcomponentPage } from './XcomponentPage';
import { ArkTSUtils, ArrayList } from '@kit.ArkTS';
import { image } from '@kit.ImageKit';
import nativeCanvas from 'libentry.so';
import { window } from '@kit.ArkUI';


@Component
struct PageTest1 {
