declare class ArkTools {
  static forceFullGC(): void
}

@Entry
@Component
struct Index {
  @State message: string = 'Hello World';
  @State buttonPosition: Position = {x: 100, y: 200};
  @State gcString: ResourceStr = "gc";


  @Provide('pageInfos') pageInfos: NavPathStack = new NavPathStack()

  @Builder
  PageMap(name: string) {
    if (name === "canvasPage") {
      PageTest1();
    } else if (name === "testPage") {
      PageTest2();
    }
  }

  private pixelmaps: ArrayList<image.PixelMap> = new ArrayList();
  private pixelmapNames: string[] = [
    "1.png",
    "2.jpeg",
    "6.jpg",
    "ski_jump_1440x960.heic"
  ]

  private picNames: string[] = [
    "1.png",
    "2.jpeg",
    "3.jpeg",
    "4.jpg",
    "6.jpg",
    "Landscape_0.jpg",
    "Landscape_1.jpg",
    "Landscape_2.jpg",
    "Landscape_3.jpg",
    "Landscape_4.jpg",
    "Landscape_5.jpg",
    "Landscape_6.jpg",
    "Landscape_7.jpg",
    "Landscape_8.jpg",
    "Portrait_0.jpg",
    "Portrait_1.jpg",
    "Portrait_2.jpg",
    "Portrait_3.jpg",
    "Portrait_4.jpg",
    "Portrait_5.jpg",
    "Portrait_6.jpg",
    "Portrait_7.jpg",
    "Portrait_8.jpg",
  ];

  private gifNames: string[] = [
    "1.gif",
    "2.webp",
    "3.webp",
    "4.gif",
  ];

  build() {
    Column() {
      Navigation(this.pageInfos) {
        Row().height(500)
        Button("跳转canvasPage")
          .fontSize(20)
          .fontWeight(FontWeight.Bold)
          .align(Alignment.Center)
          .onClick(() => {
            this.pageInfos.pushPath({name: "canvasPage"});
          }).onTouch((event: TouchEvent) => {
          console.log(`button touch type: ${event.type}`);
          this.buttonPosition = {x: event.touches[0].displayX - 50, y: event.touches[0].displayY - 50 }
        }).position(this.buttonPosition)
          .height(100)
        Row().height(50)
        Button("跳转textPage")
          .fontSize(20)
          .fontWeight(FontWeight.Bold)
          .align(Alignment.Center)
          .onClick(() => {
            this.pageInfos.pushPath({name: "testPage"});
          })
        Row().height(50)
        Button(this.gcString)
          .onClick(() => {
            console.log('force gc invoke');
            ArkTools.forceFullGC();
            this.gcString = `gcTest-${this.buttonPosition.x}-${this.buttonPosition.y}`
          })
      }
      .mode(NavigationMode.Stack)
      .hideToolBar(true)
      .hideTitleBar(true)
      .hideBackButton(true)
      .navDestination(this.PageMap)
      // XcomponentPage()
      .height("100%")
      // Text(this.message)
    }
    // .renderGroup(true)
    .height('100%')
  }

  loadPixelmap(fileName: string): image.PixelMap {
    let fileData = getContext(this).resourceManager.getRawFileContentSync(fileName);
    let buffer: ArrayBuffer = fileData?.buffer as ArrayBuffer ?? new ArrayBuffer(0);
    let imageSource: image.ImageSource = image.createImageSource(buffer);
    let imageInfo = imageSource.getImageInfo();
    let pixelMap = imageSource.createPixelMapSync();
    console.log("getPixelBytesNumber " + pixelMap.getPixelBytesNumber());

    imageSource.release()
    return pixelMap;
  }

  loadAllPic() {
    if (this.pixelmaps.length == 0) {
      for (let name of this.picNames) {
        let fileData = getContext(this).resourceManager.getRawFileContentSync(name);
        let buffer: ArrayBuffer = fileData?.buffer as ArrayBuffer ?? new ArrayBuffer(0);
        nativeCanvas.nativeAddPicData(buffer);
        // let pixemap = await this.loadPixelmap(name);
        // this.pixelmaps.add(pixemap);
        // nativeCanvas.nativeAddPixelmap(pixemap);
      }

      for (let name of this.gifNames) {
        let fileData = getContext(this).resourceManager.getRawFileContentSync(name);
        let buffer: ArrayBuffer = fileData?.buffer as ArrayBuffer ?? new ArrayBuffer(0);
        nativeCanvas.nativeAddGifData(buffer);
        // let pixemap = await this.loadPixelmap(name);
        // this.pixelmaps.add(pixemap);
        // nativeCanvas.nativeAddPixelmap(pixemap);
      }

      for (let name of this.pixelmapNames) {
        let pixemap = this.loadPixelmap(name);
        this.pixelmaps.add(pixemap);
        nativeCanvas.nativeAddPixelmap(pixemap);
      }
    }
  }

  setFontFilePath() {
    nativeCanvas.nativeSetFontPath(getContext(this).resourceDir + "/YiShanBeiZhuanTi.ttf");
  }

  aboutToAppear() {
    this.loadAllPic();
    this.setFontFilePath();
    window.getLastWindow(getContext(this)).then(result =>
    {
      result.setWindowKeepScreenOn(true) //设置窗口常亮或取消
    })
  }
}

